def _frozen() -> bool:
    return bool(getattr(sys, "frozen", False))


def _say(text: str) -> None:
    try:
        if sys.stdout is not None:
            sys.stdout.write(text + "\n")
            sys.stdout.flush()
    except Exception:  # noqa: BLE001
        pass


def norm_name(name: str) -> str:
    return re.sub(r"[-_.]+", "-", name or "").lower()


def python_tag() -> str:
    return f"cp{sys.version_info[0]}{sys.version_info[1]}"


def app_dir() -> str:
    """Folder of the EXE (frozen) or of the running script."""
    if _frozen():
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(sys.argv[0] or __file__))


def bundle_dir() -> str:
    return getattr(sys, "_MEIPASS", None) or os.path.dirname(os.path.abspath(__file__))


# ====================================================================================================
# requirement lines, versions
# ====================================================================================================

class Req:
    __slots__ = ("name", "extras", "spec", "marker", "line")

    def __init__(self, name: str, extras: str, spec: str, marker: str, line: str):
        self.name, self.extras, self.spec, self.marker, self.line = name, extras, spec.strip(), marker.strip(), line.strip()

    @property
    def key(self) -> str:
        return norm_name(self.name)

    def __repr__(self) -> str:  # pragma: no cover
        return f"Req({self.line!r})"


_REQ_RE = re.compile(r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)\s*(\[[^\]]*\])?\s*(\([^)]*\)|[<>=!~][^;#]*)?\s*(?:;\s*([^#]*))?")


def parse_requirements(text: str) -> List[Req]:
    """requirements.txt style text -> Req list. Comments, blank lines, options (-r, -e, --index-url ...) and URLs are skipped."""
    out: List[Req] = []
    for raw in (text or "").splitlines():
        line = raw.split(" #")[0].strip()
        if not line or line.startswith(("#", "-")) or "://" in line.split(";")[0] or line.startswith((".", "/")):
            continue
        m = _REQ_RE.match(line)
        if not m:
            continue
        spec = (m.group(3) or "").strip().strip("()")
        out.append(Req(m.group(1), m.group(2) or "", spec, m.group(4) or "", line))
    return out


def _vparts(v: str) -> Tuple[Tuple[int, ...], int]:
    """Version -> (numbers, 0 for a pre/dev release, 1 otherwise). Enough for ordering normal releases; never raises."""
    v = (v or "").strip().lower().lstrip("v").split("+")[0]
    nums: List[int] = []
    for p in re.split(r"[.\-_]", v):
        m = re.match(r"^(\d+)(.*)$", p)
        if not m:
            break
        nums.append(int(m.group(1)))
        if m.group(2):
            break
    pre = 0 if re.search(r"(a|b|rc|alpha|beta|pre|dev)\d*", v) and not re.search(r"post", v) else 1
    return tuple(nums) or (0,), pre


def _cmp(a: str, b: str) -> int:
    (an, ap), (bn, bp) = _vparts(a), _vparts(b)
    n = max(len(an), len(bn))
    an, bn = an + (0,) * (n - len(an)), bn + (0,) * (n - len(bn))
    if an != bn:
        return -1 if an < bn else 1
    return (ap > bp) - (ap < bp)


def spec_ok(version: str, spec: str) -> bool:
    """Is `version` allowed by a comma separated specifier ('>=1.2,<2', '==1.4.*', '~=2.1')? Unparseable -> True (never blocks a start)."""
    spec = (spec or "").strip()
    if not spec:
        return True
    for clause in [c.strip() for c in spec.split(",") if c.strip()]:
        m = re.match(r"^(===|==|!=|~=|>=|<=|>|<)\s*([^\s]+)$", clause)
        if not m:
            continue
        op, want = m.group(1), m.group(2)
        if want.endswith(".*"):
            base = want[:-2]
            pre = _vparts(version)[0][:len(_vparts(base)[0])] == _vparts(base)[0]
            if (op == "==" and not pre) or (op == "!=" and pre):
                return False
            continue
        c = _cmp(version, want)
        if op in ("==", "===") and c != 0:
            return False
        if op == "!=" and c == 0:
            return False
        if op == ">=" and c < 0:
            return False
        if op == "<=" and c > 0:
            return False
        if op == ">" and c <= 0:
            return False
        if op == "<" and c >= 0:
            return False
        if op == "~=":
            nums = _vparts(want)[0]
            if c < 0 or _vparts(version)[0][:max(1, len(nums) - 1)] != nums[:max(1, len(nums) - 1)]:
                return False
    return True


def marker_applies(marker: str) -> bool:
    """Tiny evaluator for the common markers (sys_platform, platform_system, os_name, python_version, ...). Unknown -> applies."""
    marker = (marker or "").strip()
    if not marker or "(" in marker:
        return True
    import platform
    env = {"sys_platform": sys.platform, "platform_system": platform.system(), "os_name": os.name,
           "python_version": "%d.%d" % sys.version_info[:2], "platform_machine": platform.machine(),
           "implementation_name": sys.implementation.name, "python_full_version": platform.python_version()}

    def one(term: str) -> bool:
        m = re.match(r"^\s*([a-z_]+)\s*(==|!=|<=|>=|<|>|in|not in)\s*['\"]([^'\"]*)['\"]\s*$", term)
        if not m or m.group(1) not in env:
            return True
        val, op, want = env[m.group(1)], m.group(2), m.group(3)
        if m.group(1).startswith("python"):
            c = _cmp(val, want)
            return {"==": c == 0, "!=": c != 0, "<=": c <= 0, ">=": c >= 0, "<": c < 0, ">": c > 0}.get(op, True)
        return {"==": val == want, "!=": val != want, "in": val in want, "not in": val not in want}.get(op, True)

    return any(all(one(t) for t in alt.split(" and ")) for alt in marker.split(" or "))


