def load_manifest() -> Optional[Dict[str, Any]]:
    for base in (bundle_dir(), app_dir()):
        p = os.path.join(base, MANIFEST_NAME)
        if os.path.isfile(p):
            try:
                with open(p, encoding="utf-8") as fh:
                    d = json.load(fh)
                if isinstance(d, dict):
                    return d
            except Exception:  # noqa: BLE001
                pass
    return None


def effective_requirements(manifest: Dict[str, Any], base_dir: Optional[str] = None) -> Tuple[List[Req], str]:
    """(requirements, source text). The list next to the EXE wins - that is how a library is added / changed without rebuilding -
    unless it carries the build id of an OLDER build (a stale copy left from a previous build)."""
    p = os.path.join(base_dir or app_dir(), OVERRIDE_NAME)
    if os.path.isfile(p):
        try:
            with open(p, encoding="utf-8") as fh:
                text = fh.read()
            ids = [ln.split(":", 1)[1].strip() for ln in text.splitlines() if ln.strip().lower().startswith(BUILD_ID_PREFIX)]
            parsed = parse_requirements(text)
            if parsed and (not ids or ids[0] == manifest.get("build_id")):        # an empty file never means "no libraries"
                return parsed, OVERRIDE_NAME
        except Exception:  # noqa: BLE001
            pass
    bp = os.path.join(bundle_dir(), "sorads_runtime", "requirements.txt")
    if base_dir is None and os.path.isfile(bp):
        try:
            with open(bp, encoding="utf-8") as fh:
                parsed = parse_requirements(fh.read())
            if parsed:
                return parsed, "requirements.txt (inside the application)"
        except Exception:  # noqa: BLE001
            pass
    return parse_requirements("\n".join(manifest.get("requirements") or [])), "built-in list"


def env_name(manifest: Dict[str, Any]) -> str:
    return re.sub(r"[^A-Za-z0-9._-]+", "_", str(manifest.get("env_name") or manifest.get("app_name") or "App")).strip("_") or "App"


def data_root(name: str) -> str:
    if sys.platform.startswith("win"):
        base = os.environ.get("LOCALAPPDATA") or os.path.join(os.path.expanduser("~"), "AppData", "Local")
    elif sys.platform == "darwin":
        base = os.path.join(os.path.expanduser("~"), "Library", "Application Support")
    else:
        base = os.environ.get("XDG_DATA_HOME") or os.path.join(os.path.expanduser("~"), ".local", "share")
    return os.path.join(base, name)


def config_path(manifest: Dict[str, Any]) -> str:
    return os.path.join(data_root(env_name(manifest)), CONFIG_NAME)


def load_config(manifest: Dict[str, Any]) -> Dict[str, Any]:
    cfg = {"env_dir": "", "show_on_startup": bool(manifest.get("show_on_startup", True)),
           "auto_update": bool(manifest.get("auto_update", True)), "index_url": str(manifest.get("index_url") or ""),
           "extra_index_url": str(manifest.get("extra_index_url") or ""), "configured": False}
    try:
        with open(config_path(manifest), encoding="utf-8") as fh:
            saved = json.load(fh)
        if isinstance(saved, dict):
            cfg.update({k: saved[k] for k in ("env_dir", "show_on_startup", "auto_update", "index_url", "extra_index_url") if k in saved})
            cfg["configured"] = True
    except Exception:  # noqa: BLE001
        pass
    return cfg


def save_config(manifest: Dict[str, Any], cfg: Dict[str, Any]) -> bool:
    try:
        p = config_path(manifest)
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", encoding="utf-8") as fh:
            json.dump({k: cfg.get(k) for k in ("env_dir", "show_on_startup", "auto_update", "index_url", "extra_index_url")}, fh, indent=1)
        cfg["configured"] = True
        return True
    except Exception:  # noqa: BLE001
        return False


def resolve_env_dir(manifest: Dict[str, Any], cfg: Dict[str, Any], cli_dir: str = "") -> str:
    name = env_name(manifest)
    d = (cli_dir or os.environ.get("SORADS_ENV_DIR") or os.environ.get(re.sub(r"[^A-Za-z0-9]", "_", name).upper() + "_ENV_DIR")
         or cfg.get("env_dir") or os.path.join(data_root(name), "env"))
    return os.path.abspath(os.path.expanduser(d))


def find_site_packages(env_dir: str) -> str:
    """The folder that holds the libraries inside an environment folder: a copied venv (Lib/site-packages, lib/pythonX.Y/site-packages),
    site-packages, the folder this runtime creates (site-packages-cpXY), or the packages directly in env_dir. '' when none is there."""
    import glob
    cands = [os.path.join(env_dir, "Lib", "site-packages")]
    cands += sorted(glob.glob(os.path.join(env_dir, "lib", "python*", "site-packages")), reverse=True)
    cands += [os.path.join(env_dir, "site-packages"), os.path.join(env_dir, "site-packages-" + python_tag())]
    for c in cands:
        if os.path.isdir(c):
            return c
    if os.path.isdir(env_dir) and scan_installed(env_dir):
        return env_dir
    return ""


def site_dir(env_dir: str) -> str:
    """Where the libraries are (an existing layout) - or where new ones will be installed."""
    return find_site_packages(env_dir) or os.path.join(env_dir, "site-packages-" + python_tag())


def local_env_dir(manifest: Dict[str, Any]) -> str:
    """<exe folder>/env : where a copy of the developer's environment goes."""
    return os.path.join(app_dir(), str(manifest.get("local_env_name") or "env"))


def env_override(manifest: Dict[str, Any]) -> str:
    name = env_name(manifest)
    return os.environ.get("SORADS_ENV_DIR") or os.environ.get(re.sub(r"[^A-Za-z0-9]", "_", name).upper() + "_ENV_DIR") or ""


def folder_writable(path: str) -> Tuple[bool, str]:
    try:
        os.makedirs(path, exist_ok=True)
        probe = os.path.join(path, ".sorads_write_test")
        with open(probe, "w") as fh:
            fh.write("x")
        os.remove(probe)
        return True, ""
    except Exception as ex:  # noqa: BLE001
        return False, f"{type(ex).__name__}: {ex}"[:160]


# ====================================================================================================
# what is installed
# ====================================================================================================

def scan_installed(sp: str) -> Dict[str, str]:
    """{normalized name: version} from the *.dist-info folders of a site-packages folder (no imports, milliseconds)."""
    out: Dict[str, str] = {}
    newest: Dict[str, float] = {}
    try:
        for entry in os.listdir(sp):
            if entry.endswith(".dist-info"):
                stem = entry[:-len(".dist-info")]
                if "-" in stem:
                    n, v = stem.split("-", 1)
                    key = norm_name(n)
                    try:
                        mt = os.path.getmtime(os.path.join(sp, entry))
                    except OSError:
                        mt = 0.0
                    if key not in out or mt >= newest[key]:          # two versions side by side (old leftovers): the newest wins
                        out[key], newest[key] = v, mt
    except OSError:
        pass
    return out


def remove_dist(sp: str, key: str) -> int:
    """Removes the files of an installed library (from its RECORD) and its dist-info, so a re-install / downgrade starts clean:
    `pip --target` merges into the folder and never deletes the previous version's dist-info. Returns the number of folders removed."""
    import shutil
    n = 0
    try:
        entries = os.listdir(sp)
    except OSError:
        return 0
    for entry in entries:
        if not entry.endswith(".dist-info") or "-" not in entry[:-len(".dist-info")]:
            continue
        if norm_name(entry[:-len(".dist-info")].split("-", 1)[0]) != key:
            continue
        d = os.path.join(sp, entry)
        parents = set()
        try:
            with open(os.path.join(d, "RECORD"), encoding="utf-8") as fh:
                for line in fh:
                    rel = line.split(",", 1)[0].strip().strip('"')
                    if not rel or rel.startswith(("..", "/")) or ":" in rel[:3]:
                        continue
                    full = os.path.normpath(os.path.join(sp, rel))
                    if not full.startswith(os.path.normpath(sp) + os.sep) or full.startswith(d + os.sep):
                        continue
                    try:
                        os.remove(full)
                    except OSError:
                        pass
                    parents.add(os.path.dirname(full))
        except OSError:
            pass
        for par in sorted(parents, key=len, reverse=True):          # drop folders the library left empty (never a shared, non-empty one)
            cur = par
            while cur and cur != os.path.normpath(sp) and cur.startswith(os.path.normpath(sp)):
                try:
                    os.rmdir(cur)
                except OSError:
                    break
                cur = os.path.dirname(cur)
        shutil.rmtree(d, ignore_errors=True)
        n += 1
    return n


def evaluate(reqs: List[Req], installed: Dict[str, str]) -> List[Dict[str, Any]]:
    """One row per applicable requirement: name, required (spec text), installed (version or ''), status ok | missing | update, line."""
    rows = []
    for r in reqs:
        if not marker_applies(r.marker):
            continue
        have = installed.get(r.key, "")
        if not have:
            st = "missing"
        elif not spec_ok(have, r.spec):
            st = "update"
        else:
            st = "ok"
        rows.append({"name": r.name, "required": r.spec or "any", "installed": have, "status": st, "line": r.line})
    return rows


def list_hash(reqs: List[Req]) -> str:
    h = hashlib.sha256()
    h.update(python_tag().encode())
    for r in sorted(reqs, key=lambda x: x.key):
        h.update(("%s|%s|%s\n" % (r.key, r.extras, r.spec)).encode())
    return h.hexdigest()[:16]


def read_stamp(env_dir: str) -> Dict[str, Any]:
    try:
        with open(os.path.join(env_dir, STAMP_NAME), encoding="utf-8") as fh:
            d = json.load(fh)
            return d if isinstance(d, dict) else {}
    except Exception:  # noqa: BLE001
        return {}


def write_stamp(env_dir: str, reqs: List[Req], installed: Dict[str, str]) -> None:
    try:
        os.makedirs(env_dir, exist_ok=True)
        with open(os.path.join(env_dir, STAMP_NAME), "w", encoding="utf-8") as fh:
            json.dump({"python": python_tag(), "list_hash": list_hash(reqs), "updated": time.strftime("%Y-%m-%d %H:%M:%S"),
                       "requirements": [r.line for r in reqs],
                       "installed": {r.key: installed.get(r.key, "") for r in reqs}}, fh, indent=1)
    except OSError:
        pass


# ====================================================================================================
# activating the folder
# ====================================================================================================

_DLL_HANDLES: List[Any] = []


def activate(sp: str) -> None:
    """Put the libraries on sys.path (.pth files processed) and make their DLLs findable."""
    if not sp or not os.path.isdir(sp):
        return
    import site
    if sp not in sys.path:
        site.addsitedir(sp)
    dirs = [sp]
    try:
        for entry in os.listdir(sp):
            full = os.path.join(sp, entry)
            if os.path.isdir(full) and (entry.endswith(".libs") or entry in ("pywin32_system32", "PySide6", "shiboken6", "torch", "bin")):
                dirs.append(full)
                for sub in ("lib", "bin", ".libs"):
                    if os.path.isdir(os.path.join(full, sub)):
                        dirs.append(os.path.join(full, sub))
    except OSError:
        pass
    if hasattr(os, "add_dll_directory"):
        for d in dirs:
            try:
                _DLL_HANDLES.append(os.add_dll_directory(d))
            except OSError:
                pass
    os.environ["PATH"] = os.pathsep.join(dirs) + os.pathsep + os.environ.get("PATH", "")
    os.environ[ENV_SITE] = sp
    try:
        import importlib
        importlib.invalidate_caches()
    except Exception:  # noqa: BLE001
        pass


# ====================================================================================================
# pip
# ====================================================================================================

def pip_command(args: List[str]) -> List[str]:
    """Frozen: the EXE itself re-launched as pip (see run_pip_child). Unfrozen: python -m pip."""
    if _frozen():
        return [sys.executable, PIP_FLAG] + args
    return [sys.executable, "-m", "pip"] + args


def pip_install_args(lines: List[str], sp: str, env_dir: str, cfg: Dict[str, Any]) -> List[str]:
    a = ["install", "--target", sp, "--upgrade", "--only-binary=:all:", "--disable-pip-version-check", "--no-input",
         "--progress-bar", "off", "--cache-dir", os.path.join(env_dir, ".pipcache")]
    if cfg.get("index_url"):
        a += ["--index-url", cfg["index_url"]]
    if cfg.get("extra_index_url"):
        a += ["--extra-index-url", cfg["extra_index_url"]]
    return a + list(lines)


def run_pip(args: List[str], on_line: Callable[[str], None], cancel: Optional[threading.Event] = None) -> int:
    env = dict(os.environ)
    env.update(PIP_DISABLE_PIP_VERSION_CHECK="1", PYTHONUTF8="1", PYTHONIOENCODING="utf-8", PIP_USER="0", PIP_NO_INPUT="1")
    kw: Dict[str, Any] = {}
    if sys.platform.startswith("win"):
        kw["creationflags"] = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    try:
        proc = subprocess.Popen(pip_command(args), stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL,
                                text=True, encoding="utf-8", errors="replace", env=env, bufsize=1, **kw)
    except OSError as ex:
        on_line(f"could not start pip: {ex}")
        return 99
    try:
        for line in proc.stdout:  # type: ignore[union-attr]
            on_line(line.rstrip())
            if cancel is not None and cancel.is_set():
                proc.terminate()
                on_line("cancelled")
                break
        proc.wait()
    finally:
        try:
            proc.stdout.close()  # type: ignore[union-attr]
        except Exception:  # noqa: BLE001
            pass
    return 130 if cancel is not None and cancel.is_set() else int(proc.returncode or 0)


def run_pip_child() -> None:
    """`EXE --sorads-pip <pip arguments>`: this process IS pip (the EXE bundles it). Never returns when the flag is present."""
    if len(sys.argv) > 1 and sys.argv[1] == PIP_FLAG:
        args = sys.argv[2:]
        try:
            from pip._internal.cli.main import main as pip_main
        except Exception as ex:  # noqa: BLE001
            _say(f"pip is not inside this EXE ({type(ex).__name__}: {ex}). Rebuild with 'Slim build' ticked.")
            sys.exit(97)
        sys.argv = ["pip"] + args
        sys.exit(pip_main(args))


def install(lines: List[str], reqs: List[Req], env_dir: str, cfg: Dict[str, Any], on_line: Callable[[str], None],
            cancel: Optional[threading.Event] = None) -> Tuple[bool, str]:
    """Downloads `lines` (requirement strings) into the environment folder, then verifies the WHOLE list and writes the stamp."""
    sp = site_dir(env_dir)
    ok, why = folder_writable(env_dir)
    if not ok:
        return False, f"the folder {env_dir} cannot be written ({why}) - choose another folder"
    os.makedirs(sp, exist_ok=True)
    errors: List[str] = []
    logf = _open_log(manifest_name_hint(env_dir))

    def say(s: str) -> None:
        if s.startswith("ERROR"):
            errors.append(s)
        if logf:
            try:
                logf.write(s + "\n")
                logf.flush()
            except Exception:  # noqa: BLE001
                pass
        on_line(s)

    try:
        if lines:
            for ln in lines:                                       # start from a clean slate for every library that is (re)installed
                for r in parse_requirements(ln):
                    remove_dist(sp, r.key)
            rc = run_pip(pip_install_args(lines, sp, env_dir, cfg), say, cancel)
            if rc == 130:
                return False, "cancelled"
            if rc != 0 and len(lines) > 1:
                # pip installs a list all-or-nothing: ONE library without a wheel / with a conflict would leave EVERYTHING missing.
                say("pip could not install the whole list - trying the libraries one by one so the others still get installed ...")
                for ln in lines:
                    for r in parse_requirements(ln):
                        remove_dist(sp, r.key)
                    rc1 = run_pip(pip_install_args([ln], sp, env_dir, cfg), say, cancel)
                    if rc1 == 130:
                        return False, "cancelled"
                    if rc1 != 0:
                        say(f"ERROR: could not install {ln}")
            elif rc != 0:
                return False, _pip_failure(rc, errors)
        rows = evaluate(reqs, scan_installed(sp))
        bad = [r for r in rows if r["status"] != "ok"]
        if bad:
            return False, _incomplete(rows, bad, errors, logf)
        write_stamp(env_dir, reqs, scan_installed(sp))
        return True, "all libraries are ready"
    finally:
        if logf:
            try:
                logf.close()
            except Exception:  # noqa: BLE001
                pass


def manifest_name_hint(env_dir: str) -> str:
    return os.path.join(env_dir, "sorads_setup.log")


def _open_log(path: str):
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        fh = open(path, "a", encoding="utf-8")
        fh.write("\n=== %s  python %s ===\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), python_tag()))
        return fh
    except Exception:  # noqa: BLE001
        return None


def _last_error(errors: List[str]) -> str:
    useful = [e for e in errors if "could not install" not in e]
    return (useful[-1] if useful else (errors[-1] if errors else ""))[:260]


def _pip_failure(rc: int, errors: List[str]) -> str:
    why = _last_error(errors)
    return (f"pip stopped with code {rc}. " + (why + ". " if why else "") +
            "Check the internet connection (or a proxy / the index URL), then try again; "
            "a library without a ready-made wheel for this Python cannot be installed by the EXE.")


def _incomplete(rows, bad, errors, logf) -> str:
    ok_n = len(rows) - len(bad)
    names = ", ".join(r["name"] for r in bad)
    why = _last_error(errors)
    return (f"{ok_n} of {len(rows)} libraries are installed. NOT installed: {names}. " + (why + " " if why else "") +
            "Press the download button to try again" + (f" (details: {logf.name})" if logf else "") + ".")


# ====================================================================================================
# the window
# ====================================================================================================

def tk_available() -> bool:
    try:
        import tkinter
        r = tkinter.Tk()
        r.withdraw()
        r.destroy()
        return True
    except Exception:  # noqa: BLE001
        return False


class SetupDialog:
    """The environment window. run() returns 'start' or 'exit'."""

    def __init__(self, manifest, cfg, env_dir, reqs, source, stay=False, auto_install=False, countdown=3, installer=None, first_run=False):
        import tkinter as tk
        from tkinter import ttk, filedialog
        self.tk, self.ttk, self.filedialog = tk, ttk, filedialog
        self.manifest, self.cfg, self.reqs, self.source = manifest, cfg, reqs, source
        self.env_dir = env_dir
        self.stay, self.countdown0 = stay, countdown
        self.first_run = first_run
        self.installer = installer or install
        self.result = "exit"
        self.busy = False
        self.cancel = threading.Event()
        self.q: "list" = []
        self.lock = threading.Lock()
        self.left = 0
        app = str(manifest.get("app_name") or "Application")
        self.root = tk.Tk()
        self.root.title(f"{app} - first start: choose the environment folder" if first_run else f"{app} - environment and libraries")
        self.root.geometry("820x600")
        self.root.minsize(640, 480)
        self.root.protocol("WM_DELETE_WINDOW", self._exit)
        self.v_dir = tk.StringVar(value=env_dir)
        self.v_show = tk.BooleanVar(value=bool(cfg.get("show_on_startup", True)))
        self.v_auto = tk.BooleanVar(value=bool(cfg.get("auto_update", True)))
        self.v_index = tk.StringVar(value=str(cfg.get("index_url") or ""))
        self.v_status = tk.StringVar()
        self._build(app)
        self.refresh()
        self.root.after(250, self._pump)
        if first_run:
            self.v_status.set("First start: choose the folder where the libraries are stored, then press 'Install libraries'.")
        elif auto_install and self._todo():
            self.root.after(400, lambda: self.start_install(False))
        elif not self._todo() and not stay and self.v_show.get():
            self._start_countdown(countdown)

    # ---- layout
    def _build(self, app: str) -> None:
        tk, ttk = self.tk, self.ttk
        f = ttk.Frame(self.root, padding=10)
        f.pack(fill="both", expand=True)
        f.columnconfigure(1, weight=1)
        f.rowconfigure(3, weight=1)
        intro = (f"{app} keeps its libraries outside the program, so the program is small and starts fast.\n"
                 "They are downloaded once into this folder and only updated when the list of libraries changes.")
        if self.first_run:
            intro = (f"Welcome. Where should {app} store its libraries?  (a folder with enough free space; you can change it later)\n"
                     "The list comes from the requirements.txt inside the application. Nothing is downloaded until you press the button.")
        lbl = ttk.Label(f, text=intro, justify="left", wraplength=780)
        lbl.grid(row=0, column=0, columnspan=4, sticky="w")
        def _rewrap(e, l=lbl):
            if e.widget is self.root:
                w = max(300, self.root.winfo_width() - 40)
                l.configure(wraplength=w)
                self.lbl_status.configure(wraplength=w)
        self.root.bind("<Configure>", _rewrap)
        ttk.Label(f, text="Environment folder:").grid(row=1, column=0, sticky="w", pady=(8, 2))
        e = ttk.Entry(f, textvariable=self.v_dir)
        e.grid(row=1, column=1, sticky="ew", pady=(8, 2), padx=6)
        e.bind("<Return>", lambda _e: self._dir_changed())
        e.bind("<FocusOut>", lambda _e: self._dir_changed())
        ttk.Button(f, text="Browse...", command=self._browse).grid(row=1, column=2, pady=(8, 2))
        ttk.Button(f, text="Open", command=self._open_dir).grid(row=1, column=3, pady=(8, 2), padx=(4, 0))
        self.lbl_status = ttk.Label(f, textvariable=self.v_status, foreground="#555", wraplength=780, justify="left")
        self.lbl_status.grid(row=2, column=0, columnspan=4, sticky="w", pady=(2, 4))
        cols = ("lib", "req", "have", "state")
        self.tree = ttk.Treeview(f, columns=cols, show="headings", height=9)
        for c, t, w in (("lib", "Library", 220), ("req", "Required", 150), ("have", "Installed", 150), ("state", "Status", 150)):
            self.tree.heading(c, text=t)
            self.tree.column(c, width=w, anchor="w")
        self.tree.tag_configure("ok", foreground="#1a7f37")
        self.tree.tag_configure("missing", foreground="#b42318")
        self.tree.tag_configure("update", foreground="#b54708")
        sb = ttk.Scrollbar(f, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        self.tree.grid(row=3, column=0, columnspan=3, sticky="nsew")
        sb.grid(row=3, column=3, sticky="ns")
        opt = ttk.Frame(f)
        opt.grid(row=4, column=0, columnspan=4, sticky="ew", pady=(6, 0))
        opt.columnconfigure(3, weight=1)
        ttk.Checkbutton(opt, text="Show this window every time the program starts", variable=self.v_show, command=self._opts_changed).grid(row=0, column=0, sticky="w")
        ttk.Checkbutton(opt, text="Download missing / changed libraries automatically", variable=self.v_auto, command=self._opts_changed).grid(row=1, column=0, sticky="w")
        ttk.Label(opt, text="Package index URL (optional mirror):").grid(row=0, column=2, sticky="e", padx=(12, 4))
        ie = ttk.Entry(opt, textvariable=self.v_index, width=34)
        ie.grid(row=0, column=3, sticky="ew")
        ie.bind("<FocusOut>", lambda _e: self._opts_changed())
        self.bar = ttk.Progressbar(f, mode="determinate", maximum=100)
        self.bar.grid(row=5, column=0, columnspan=4, sticky="ew", pady=(8, 2))
        self.log = tk.Text(f, height=6, wrap="word", state="disabled", font=("Consolas", 9) if sys.platform.startswith("win") else ("monospace", 9))
        self.log.grid(row=6, column=0, columnspan=4, sticky="ew")
        row = ttk.Frame(f)
        row.grid(row=7, column=0, columnspan=4, sticky="ew", pady=(8, 0))
        self.b_dl = ttk.Button(row, text="Install libraries" if self.first_run else "Download / update libraries",
                               command=lambda: self.start_install(False))
        self.b_dl.pack(side="left")
        self.b_all = ttk.Button(row, text="Re-download all", command=lambda: self.start_install(True))
        self.b_all.pack(side="left", padx=6)
        self.b_exit = ttk.Button(row, text="Exit", command=self._exit)
        self.b_exit.pack(side="right")
        self.b_go = ttk.Button(row, text="Start application", command=self._go)
        self.b_go.pack(side="right", padx=6)
        self.root.bind("<Key>", lambda _e: self._stop_countdown())
        self.root.bind("<Button-1>", lambda _e: self._stop_countdown())

    # ---- state
    def _todo(self) -> List[str]:
        rows = evaluate(self.reqs, scan_installed(site_dir(self.env_dir)))
        return [r["line"] for r in rows if r["status"] != "ok"]

    def refresh(self) -> None:
        rows = evaluate(self.reqs, scan_installed(site_dir(self.env_dir)))
        self.tree.delete(*self.tree.get_children())
        label = {"ok": "ready", "missing": "needs download", "update": "needs update"}
        for r in rows:
            self.tree.insert("", "end", values=(r["name"], r["required"], r["installed"] or "-", label[r["status"]]), tags=(r["status"],))
        need = sum(1 for r in rows if r["status"] != "ok")
        self.v_status.set((f"{need} of {len(rows)} libraries need downloading / updating" if need else f"All {len(rows)} libraries are ready")
                          + f"   (list: {self.source})")
        self.b_go.configure(text="Start application" if not need else ("Start without libraries" if self.first_run else "Start anyway"))

    def _append(self, text: str) -> None:
        self.log.configure(state="normal")
        self.log.insert("end", text.rstrip() + "\n")
        self.log.see("end")
        self.log.configure(state="disabled")

    def _opts_changed(self) -> None:
        self._stop_countdown()
        self.cfg.update(show_on_startup=bool(self.v_show.get()), auto_update=bool(self.v_auto.get()), index_url=self.v_index.get().strip(),
                        env_dir=self.env_dir)                              # the chosen folder is remembered from now on
        save_config(self.manifest, self.cfg)

    def _dir_changed(self) -> None:
        d = os.path.abspath(os.path.expanduser(self.v_dir.get().strip() or self.env_dir))
        if d != self.env_dir:
            self._stop_countdown()
            ok, why = folder_writable(d)
            if not ok:
                self.v_status.set(f"Cannot use that folder: {why}")
                self.v_dir.set(self.env_dir)
                return
            self.env_dir = d
            self.cfg["env_dir"] = d
            save_config(self.manifest, self.cfg)
            self.refresh()

    def _browse(self) -> None:
        self._stop_countdown()
        d = self.filedialog.askdirectory(parent=self.root, title="Choose the environment folder", initialdir=self.env_dir)
        if d:
            self.v_dir.set(d)
            self._dir_changed()

    def _open_dir(self) -> None:
        try:
            os.makedirs(self.env_dir, exist_ok=True)
            if sys.platform.startswith("win"):
                os.startfile(self.env_dir)  # type: ignore[attr-defined]  # noqa: S606
            else:
                subprocess.Popen(["open" if sys.platform == "darwin" else "xdg-open", self.env_dir])
        except Exception:  # noqa: BLE001
            pass

    # ---- countdown
    def _start_countdown(self, n: int) -> None:
        self.left = n
        self._tick()

    def _tick(self) -> None:
        if self.left <= 0:
            if self.left == 0 and not self.busy:
                self._go()
            return
        self.b_go.configure(text=f"Start application ({self.left})")
        self.left -= 1
        self.root.after(1000, self._tick)

    def _stop_countdown(self) -> None:
        if self.left > 0:
            self.left = -1
            self.b_go.configure(text="Start application" if not self._todo() else "Start anyway")

    # ---- install
    def start_install(self, everything: bool) -> None:
        if self.busy:
            return
        self._stop_countdown()
        self._opts_changed()
        lines = [r.line for r in self.reqs if marker_applies(r.marker)] if everything else self._todo()
        if not lines:
            self.v_status.set("Nothing to download - everything is ready.")
            return
        self.busy = True
        self.cancel.clear()
        for b in (self.b_dl, self.b_all):
            b.configure(state="disabled")
        self.b_exit.configure(text="Cancel", command=self._cancel_install)
        self.bar.configure(mode="indeterminate")
        self.bar.start(12)
        self._append(f"downloading {len(lines)} librar{'y' if len(lines) == 1 else 'ies'} into {site_dir(self.env_dir)}")
        total = len(lines)
        seen = {"n": 0}

        def on_line(s: str) -> None:
            if s.startswith(("Collecting", "Downloading", "Installing", "Successfully", "ERROR", "WARNING", "cancelled")):
                with self.lock:
                    self.q.append(("log", s))
            if s.startswith("Collecting"):
                seen["n"] += 1
                with self.lock:
                    self.q.append(("frac", min(0.95, seen["n"] / float(max(total, seen["n"]) + 4))))

        def work() -> None:
            try:
                ok, msg = self.installer(lines, self.reqs, self.env_dir, self.cfg, on_line, self.cancel)
            except Exception as ex:  # noqa: BLE001
                ok, msg = False, f"{type(ex).__name__}: {ex}"
            with self.lock:
                self.q.append(("done", (ok, msg)))
        threading.Thread(target=work, daemon=True).start()

    def _cancel_install(self) -> None:
        self.cancel.set()
        self.v_status.set("Cancelling ...")

    def _pump(self) -> None:
        with self.lock:
            items, self.q = self.q, []
        for kind, val in items:
            if kind == "log":
                self._append(val)
            elif kind == "frac":
                if str(self.bar.cget("mode")) != "determinate":
                    self.bar.stop()
                    self.bar.configure(mode="determinate")
                self.bar["value"] = val * 100
            elif kind == "done":
                ok, msg = val
                self.busy = False
                self.bar.stop()
                self.bar.configure(mode="determinate")
                self.bar["value"] = 100 if ok else 0
                for b in (self.b_dl, self.b_all):
                    b.configure(state="normal")
                self.b_exit.configure(text="Exit", command=self._exit)
                self.refresh()
                self._append(msg)
                self.v_status.set(msg)
                if ok and not self.stay:
                    self._start_countdown(2)
        try:
            self.root.after(200, self._pump)
        except Exception:  # noqa: BLE001
            pass

    # ---- leaving
    def _go(self) -> None:
        missing = [r["name"] for r in evaluate(self.reqs, scan_installed(site_dir(self.env_dir))) if r["status"] != "ok"]
        if missing and not self.busy:
            self._stop_countdown()
            from tkinter import messagebox
            shown = ", ".join(missing[:8]) + (" ..." if len(missing) > 8 else "")
            if not messagebox.askyesno("Libraries missing",
                                       f"These libraries are not installed yet:\n{shown}\n\nThe program will probably stop with "
                                       "\"No module named ...\".\n\nStart anyway?", icon="warning", parent=self.root):
                return
        self._opts_changed()
        self.result = "start"
        self.root.destroy()

    def _exit(self) -> None:
        if self.busy:
            self.cancel.set()
        self.result = "exit"
        self.root.destroy()

    def run(self) -> str:
        self.root.mainloop()
        return self.result


# ====================================================================================================
# console fallback + the entry point
# ====================================================================================================

def console_flow(reqs, env_dir, cfg, lines) -> bool:
    _say(f"[setup] downloading {len(lines)} librar{'y' if len(lines) == 1 else 'ies'} into {site_dir(env_dir)} ...")
    ok, msg = install(lines, reqs, env_dir, cfg, lambda s: _say("  " + s) if s.startswith(("Collecting", "Installing", "Successfully", "ERROR")) else None)
    _say("[setup] " + msg)
    return ok


def _take_flag(argv: List[str], flag: str, with_value: bool = False) -> Tuple[bool, str]:
    for i, a in enumerate(argv[1:], 1):
        if a == flag or (with_value and a.startswith(flag + "=")):
            if with_value:
                val = a.split("=", 1)[1] if "=" in a else (argv[i + 1] if i + 1 < len(argv) else "")
                del argv[i:i + (1 if "=" in a else 2)]
                return True, val
            del argv[i]
            return True, ""
    return False, ""


def is_child_process(argv: List[str]) -> bool:
    return (os.environ.get(ENV_DONE) == "1" or any(a.startswith("--multiprocessing") for a in argv)
            or "--pba-worker" in argv or (len(argv) > 1 and argv[1] == PIP_FLAG))


def run_bootstrap(argv: Optional[List[str]] = None, interactive: Optional[bool] = None, dialog_cls=None) -> str:
    """The whole startup logic. Returns 'start' (continue into the application), 'exit' (user quit) or 'none' (nothing to do).
    argv is edited in place: the bootstrap flags are removed."""
    argv = sys.argv if argv is None else argv
    manifest = load_manifest()
    if not manifest or not manifest.get("requirements"):
        return "none"
    if is_child_process(argv):
        sp = os.environ.get(ENV_SITE, "")
        if sp:
            activate(sp)
        return "none"
    force_setup, _ = _take_flag(argv, "--setup")
    no_setup, _ = _take_flag(argv, "--no-setup")
    update_all, _ = _take_flag(argv, "--update-libs")
    _, cli_dir = _take_flag(argv, "--env-dir", with_value=True)
    cfg = load_config(manifest)
    env_dir = resolve_env_dir(manifest, cfg, cli_dir)
    used_local = False
    local = local_env_dir(manifest)
    if (not cli_dir and not env_override(manifest) and os.path.isdir(local)
            and (manifest.get("mode") == "local" or not cfg["configured"])):
        env_dir, used_local = local, True                        # the developer's environment copied next to the EXE
    if cli_dir:
        cfg["env_dir"] = env_dir
    reqs, source = effective_requirements(manifest)
    sp = site_dir(env_dir)
    rows = evaluate(reqs, scan_installed(sp))
    need = [r["line"] for r in rows if r["status"] != "ok"]
    if update_all:
        need = [r["line"] for r in rows] or need
    show = (force_setup or update_all or bool(need) or (not cfg["configured"] and not used_local) or bool(cfg.get("show_on_startup"))) \
        and not (no_setup and not need)
    if not need and not show:
        activate(sp)
        os.environ[ENV_DONE] = "1"
        return "start"
    if interactive is None:
        interactive = tk_available()
    result = "start"
    if show and not no_setup and interactive:
        try:
            first = not cfg["configured"] and not cli_dir and not used_local     # first start: ASK for the folder, download nothing yet
            dlg = (dialog_cls or SetupDialog)(manifest, cfg, env_dir, reqs, source, stay=bool(force_setup or update_all),
                                              auto_install=bool(need and cfg.get("auto_update", True) and not first),
                                              countdown=int(manifest.get("countdown", 3)), first_run=first)
            if update_all:
                dlg.root.after(500, lambda: dlg.start_install(True))
            result = dlg.run()
            env_dir = dlg.env_dir
            sp = site_dir(env_dir)
        except Exception as ex:  # noqa: BLE001
            _say(f"[setup] window failed ({type(ex).__name__}: {ex}); continuing in text mode")
            interactive = False
    if result == "exit":
        return "exit"
    if not interactive and need:
        console_flow(reqs, env_dir, cfg, need)
    if not cfg["configured"]:
        save_config(manifest, cfg)
    activate(sp)
    os.environ[ENV_DONE] = "1"
    return "start"


def _hook_main() -> None:
    run_pip_child()                                   # `EXE --sorads-pip ...` is pip, nothing else
    if run_bootstrap() == "exit":
        sys.exit(0)


if _frozen():                                          # as a PyInstaller runtime hook this runs before the application's main script
    _hook_main()
elif __name__ == "__main__":
    print("runtime_bootstrap.py is the runtime of a SORADS slim build; it runs inside the built EXE.")
